// Grid BFS with the idioms from this lesson: safe grid, head-pointer queue, typed directions.
function shortestSteps(grid: string[], start: [number, number], goal: [number, number]): number {
  const rows = grid.length, cols = grid[0]?.length ?? 0;
  const dist = Array.from({ length: rows }, () => new Array<number>(cols).fill(-1));
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]] as const;
  const queue: [number, number][] = [start];
  dist[start[0]][start[1]] = 0;
  for (let head = 0; head < queue.length; head++) {
    const [r, c] = queue[head];
    if (r === goal[0] && c === goal[1]) return dist[r][c];
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (grid[nr]?.[nc] === '.' && dist[nr][nc] === -1) {
        dist[nr][nc] = dist[r][c] + 1;
        queue.push([nr, nc]);
      }
    }
  }
  return -1;
}

