type Entry = [word: string, count: number];

function topKWords(words: string[], k: number): string[] {
  const counts = new Map<string, number>();
  for (const w of words) counts.set(w, (counts.get(w) ?? 0) + 1);
  // The root is the weakest kept entry: lowest count, then the later word.
  const weaker = (a: Entry, b: Entry): boolean => (a[1] !== b[1] ? a[1] < b[1] : a[0] > b[0]);
  const heap = new MinHeap<Entry>(weaker);
  for (const entry of counts) {
    heap.push(entry);
    if (heap.size > k) heap.pop();
  }
  const out: string[] = [];
  for (let e = heap.pop(); e !== undefined; e = heap.pop()) out.push(e[0]);
  return out.reverse();
}

Count once with a `Map` (no prototype collisions, keys stay strings in insertion order). The heap's `less` puts the weakest entry at the root: a lower count is weaker, and for equal counts the later word is weaker, because it is the one that loses the tie. Pushing every distinct entry and popping whenever the size exceeds k leaves exactly the k strongest. Popping yields weakest first, so the collected words are reversed at the end. The starter sorts by count only, so ties come out in first-seen order rather than alphabetical order, and it sorts all u entries. The heap version costs O(n) to count plus O(u log k) to select, and O(u + k) space. `k = 0` pushes and immediately pops each entry, which returns `[]`.

