function makeGrid<T>(rows: number, cols: number, init: (r: number, c: number) => T): T[][] {
  return Array.from({ length: rows }, (_, r) => Array.from({ length: cols }, (_, c) => init(r, c)));
}

function paintCells(rows: number, cols: number, cells: [number, number][]): number[][] {
  const grid = makeGrid(rows, cols, () => 0);
  for (const [r, c] of cells) {
    if (r >= 0 && r < rows && c >= 0 && c < cols) grid[r][c]++;
  }
  return grid;
}

type Comparator<T> = (a: T, b: T) => number;

function thenBy<T>(...comparators: Comparator<T>[]): Comparator<T> {
  return (a, b) => {
    for (const cmp of comparators) {
      const d = cmp(a, b);
      if (d !== 0) return d;
    }
    return 0;
  };
}

interface Runner { name: string; time: number | null; bib: number }

function rankRunners(runners: Runner[]): string[] {
  const finishersFirst: Comparator<Runner> = (a, b) => Number(a.time === null) - Number(b.time === null);
  const fasterFirst: Comparator<Runner> = (a, b) => (a.time === null || b.time === null ? 0 : a.time - b.time);
  const lowerBibFirst: Comparator<Runner> = (a, b) => a.bib - b.bib;
  return runners.toSorted(thenBy(finishersFirst, fasterFirst, lowerBibFirst)).map(r => r.name);
}

